def filter_trajectories_by_setting(
    trajectories: List[DayTrajectory],
    setting: str,
) -> List[DayTrajectory]:
    # settings: '2019-2019', '2021-2021', '2019-2021'
    if setting == "2019-2019":
        return [t for t in trajectories if t.d.year in (2019, 2020)]
    if setting == "2021-2021":
        return [t for t in trajectories if t.d.year == 2021]
