def holdout_split_by_setting(
    trajectories: List[DayTrajectory],
    setting: str,
) -> Dict[str, Dict[str, List[DayTrajectory]]]:
    by_agent: Dict[str, List[DayTrajectory]] = {}
    for t in trajectories:
        by_agent.setdefault(t.agent_id, []).append(t)

    split: Dict[str, Dict[str, List[DayTrajectory]]] = {}
    for aid, days in by_agent.items():
        days_sorted = sorted(days, key=lambda x: x.d)
        if setting == "2019-2021":
            train_days = [d for d in days_sorted if d.d.year in (2019, 2020)]
            val_days = [d for d in days_sorted if d.d.year == 2021]
            if not train_days:
                # fallback to temporal split if missing years
                train_days, val_days = days_sorted[: max(1, len(days_sorted) // 2)], days_sorted[max(1, len(days_sorted) // 2) :]
        else:
            n = len(days_sorted)
            if n <= 1:
                train_days, val_days = days_sorted, []
            else:
                train_n = max(1, min(n - 1, int(math.floor(0.8 * n))))
                train_days, val_days = days_sorted[:train_n], days_sorted[train_n:]
        split[aid] = {"train": train_days, "validation": val_days}
    return split
